insert into public.questions (id, category, en, zh, enabled, sort) values
('sp085', 'spicy', 'Have you ever secretly looked up someone here on social media?', '你有没有偷偷搜索过在场某个人的社交账号？', true, 84),
('sp086', 'spicy', 'Whose WeChat here have you wanted, but never dared to ask for?', '在场谁的微信你最想要，但一直没好意思要？', true, 85),
('sp087', 'spicy', 'Who here would be most sought-after at a matchmaking corner?', '如果在场的人都站到相亲角，你觉得谁会最抢手？', true, 86),
('sp088', 'spicy', 'If you had to pair up with someone here for a dating show, who?', '如果必须和在场一个人组队上恋综，你选谁？', true, 87),
('sp089', 'spicy', 'Do you group-hide your WeChat Moments? Who gets hidden the most?', '你朋友圈有没有分组屏蔽？谁被屏蔽得最多？', true, 88),
('sp090', 'spicy', 'What''s the most times you''ve edited a post before publishing it?', '你发朋友圈之前，最多修改过多少次？', true, 89),
('sp091', 'spicy', 'Have you ever posted a Moment visible only to yourself? What kind?', '你有没有发过“仅自己可见”的朋友圈？是什么类型的内容？', true, 90),
('sp092', 'spicy', 'Have you ever posted something just so one specific person would see it?', '你有没有为了让某个人看到而故意发朋友圈？', true, 91),
('sp093', 'spicy', 'When did you last tell a lie, and what was it?', '你最近一次说谎是什么时候？说了什么？', true, 92),
('sp094', 'spicy', 'Have you ever gone through a partner''s or ex''s phone? Find anything?', '你有没有翻过现任/前任的手机？发现了什么？', true, 93),
('sp095', 'spicy', 'What was your most brutal rejection like?', '你被拒绝过最惨的一次是什么样的？', true, 94),
('sp096', 'spicy', 'How many times have you confessed feelings — and what''s your success rate?', '你表白过几次？成功率是多少？', true, 95),
('sp097', 'spicy', 'Have you ever been “talking” to two people at the same time?', '你有没有同时暧昧过两个人？', true, 96),
('sp098', 'spicy', 'How many close opposite-gender friends can your partner have? Where''s the line?', '你能接受对象有几个异性好友？界限在哪里？', true, 97),
('sp099', 'spicy', 'What''s the one dating criterion you never say out loud but matters most?', '你的择偶标准里，哪一条你嘴上不说但其实最重要？', true, 98),
('sp100', 'spicy', 'Have you ever felt sour at someone''s wedding or relationship announcement?', '你有没有在别人官宣恋爱/婚礼时酸过？', true, 99),
('sp101', 'spicy', 'If your longtime crush confessed to you right now, would you actually hesitate?', '如果你暗恋的人现在向你表白，你其实会犹豫吗？为什么？', true, 100),
('sp102', 'spicy', 'Are you a hopeless romantic? What''s your worst “恋爱脑” episode?', '你觉得自己是恋爱脑吗？最恋爱脑的一次是什么？', true, 101),
('sp103', 'spicy', 'What''s the most embarrassing thing you did after a breakup or rejection?', '你分手或被拒后，做过最丢脸的事是什么？', true, 102),
('sp104', 'spicy', 'Have you ever acted busy or popular in front of someone you liked?', '你有没有在喜欢的人面前故意装忙、装抢手？', true, 103)
insert into public.dares (id, level, en, zh, enabled, sort) values
('dr031', 'mild', 'Act out a Bible character''s entrance until people guess who.', '模仿一位圣经人物出场，直到大家猜出是谁。', true, 30),
('dr032', 'mild', 'Show the group your best party trick — anything counts.', '给大家表演你最拿手的看家本领，什么都行。', true, 31),
('dr033', 'mild', 'Re-enter the room in slow motion, with your own sound effects.', '用慢动作重现你今天进门的样子，自己配音效。', true, 32),
('dr034', 'mild', 'Serenade a pillow with the chorus of any love song.', '抱着一个抱枕，深情演唱一首歌的副歌。', true, 33),
('dr035', 'mild', 'Play rock-paper-scissors with anyone — the loser performs an animal sound chosen by the winner.', '和在场一人玩石头剪刀布，输的人学赢家指定的动物叫。', true, 34),
('dr036', 'medium', 'Let the group give you three random words; improvise a 30-second story using all of them.', '让大家出三个词，用它们即兴编一段30秒的小故事。', true, 35),
('dr037', 'medium', 'Broadcast “tonight''s fellowship news” in a formal news-anchor voice.', '用新闻主播腔播报“今晚团契大事件”。', true, 36),
('dr038', 'medium', 'Let the person on your right restyle your hair for 10 seconds; keep it for 30 minutes.', '让右边的人给你抓10秒头发，造型保持30分钟。', true, 37),
('dr039', 'medium', 'Swap one wearable item (jacket, glasses, watch) with someone until the game ends.', '和在场一人交换一件随身物品（外套、眼镜、手表），直到游戏结束。', true, 38),
('dr040', 'medium', 'Answer the next question while holding a squat.', '深蹲姿势保持不动，回答下一个问题。', true, 39),
('dr041', 'medium', 'Give a formal 30-second welcome speech honoring the newest member of the fellowship.', '给最新加入团契的人做一个正式的30秒欢迎致辞。', true, 40),
('dr042', 'bold', 'Let someone write one sentence on your arm in washable pen — keep it until tonight ends.', '让在场一人用水性笔在你手臂上写一句话，保留到今晚结束。', true, 41),
('dr043', 'bold', 'Post a single “。” in the fellowship group chat and don''t explain for 10 minutes.', '在团契群里只发一个“。”，十分钟内不许解释。', true, 42),
('dr044', 'bold', 'For your next two turns, everything you say must rhyme.', '接下来两轮，你说的每句话都必须押韵。', true, 43),
('dr045', 'mild', 'Act out yourself being woken up by your alarm on a Monday morning.', '表演“周一早上被闹钟叫醒的你”。', true, 44),
('dr046', 'mild', 'Read a nursery rhyme with a completely serious face — no smiling allowed.', '用最严肃的表情念一段儿歌，不许笑。', true, 45),
('dr047', 'mild', 'Do a runway walk around the room while everyone hums the background music.', '现场走秀绕场一圈，BGM由大家现场哼。', true, 46),
('dr048', 'mild', 'Imitate the sound of a musical instrument until someone guesses it.', '模仿一种乐器的声音，直到有人猜出来。', true, 47),
('dr049', 'mild', 'Name 10 fruits within 10 seconds — fail and draw another dare.', '10秒内说出10种水果，失败再抽一张大冒险。', true, 48),
('dr050', 'mild', 'Write “我爱我们团契” with your non-dominant hand and let everyone inspect it.', '用非惯用手写“我爱我们团契”，给大家检查。', true, 49),
('dr051', 'mild', 'Act out “pretending to be on an important call in an elevator with no signal”.', '表演“电梯里没信号却要假装通话很忙”。', true, 50),
('dr052', 'mild', 'For one round, you may only reply to people using song lyrics.', '接下来一轮，别人对你说什么，你都只能用歌词回答。', true, 51),
('dr053', 'mild', 'Mirror challenge: face a partner and copy their every move for 30 seconds without laughing.', '双人镜子挑战：面对面，对方做什么你同步模仿30秒，不许笑。', true, 52),
('dr054', 'mild', 'Blindfolded, identify three objects the group places in your hands.', '蒙上眼睛，摸出大家放到你手里的三样东西。', true, 53),
('dr055', 'medium', 'High-note challenge: sing the last line of 青藏高原 — or the highest note of any song.', '高音挑战：唱《青藏高原》最后一句，或任何歌的最高音。', true, 54),
('dr056', 'medium', 'Predictive-text challenge: type “我”, tap the first suggestion 10 times, and read the sentence aloud.', '输入法联想挑战：打一个“我”，连点联想词10次，把生成的句子读出来。', true, 55),
('dr057', 'medium', 'Bible-story charades: the person on your right acts one out silently; guess it within 30 seconds.', '圣经比划猜：右边的人无声比划一个圣经故事，你30秒内猜出。', true, 56),
('dr058', 'medium', 'Sing “Hallelujah” three times in vocal fry or full opera voice.', '用气泡音或美声唱三遍“哈利路亚”。', true, 57),
('dr059', 'medium', 'Perform a nursery rhyme chosen by the group in rock or opera style.', '用摇滚或歌剧腔演唱一首大家选的儿歌。', true, 58),
('dr060', 'medium', 'Mind-meld: you and a partner shout “the world''s tastiest food” at the same time — pass when you match; each miss costs you both 5 squats (max 3 tries).', '和对面的人同时喊“最好吃的食物”，喊到同一样才过关，不同则各做5个深蹲（最多三轮）。', true, 59),
('dr061', 'medium', 'Let the group restyle you with anything on hand (jackets, glasses, hair ties) — keep the look for two rounds.', '让大家用手边任何东西给你凹一个新造型，保持两轮。', true, 60),
('dr062', 'medium', 'Show everyone today''s real screen time (or step count).', '把你的屏幕使用时间或微信步数打开，给大家看今天的真实数据。', true, 61),
('dr063', 'medium', 'Invent a nickname for every person in the room, on the spot, until everyone approves.', '现场给在场每个人各编一个外号，大家满意才过关。', true, 62),
('dr064', 'medium', 'Compose and recite a two-line acrostic poem starting with someone''s name.', '用在场一个人的名字开头，现场作一首两句“藏头诗”并朗读。', true, 63),
('dr065', 'medium', 'Call a good friend and say, dead serious: “I have a secret — I''m actually a mermaid.” Hold for 10 seconds before explaining.', '打电话给好朋友，认真地说“我告诉你一个秘密：其实我是一条美人鱼”，撑10秒再解释。', true, 64),
('dr066', 'bold', 'Immunity flip: everyone asks you one question and you must answer honestly (you may skip one).', '豁免翻转：在场每人向你提一个问题，必须诚实回答（可跳过一个）。', true, 65),
('dr067', 'bold', 'Raise one hand, shout “I''m Superman and I''m going home!”, and do a flying lap around the room.', '举手大喊“我是超人，我要回家了！”然后摆飞行姿势绕场一圈。', true, 66),
('dr068', 'bold', 'Recite the Lord''s Prayer; every stumble costs one jumping jack before continuing.', '背诵主祷文，卡住一次做一个开合跳再继续。', true, 67),
('dr069', 'bold', 'Improvise and perform a 15-second personal theme song for the person on your left.', '给左边的人即兴创作并演唱15秒“专属主题曲”。', true, 68),
('dr070', 'bold', 'Group selfie with you making the most exaggerated face up front — post it to the fellowship group chat.', '全组自拍，你在最前面摆最夸张的表情，照片发到团契群。', true, 69)
